const $=s=>document.querySelector(s);
const intro=$('#intro'), game=$('#game'), ending=$('#ending');
function shuffle(list){const copy=[...list];for(let i=copy.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[copy[i],copy[j]]=[copy[j],copy[i]]}return copy}
function drawUnseen(key,pool){
  let seen=[];try{seen=JSON.parse(localStorage.getItem(key)||'[]')}catch{}
  let available=pool.filter(item=>!seen.includes(item.id));if(!available.length){seen=[];available=[...pool]}
  const picked=available[Math.floor(Math.random()*available.length)];seen.push(picked.id);try{localStorage.setItem(key,JSON.stringify(seen))}catch{}return picked;
}
function startGame(){
  clearMiniTimers();state.stats={...START_STATS};
  const questions=shuffle(EVENTS.filter(e=>!e.type).map(e=>JSON.parse(JSON.stringify(e)))).slice(0,10);
  const miniGames=shuffle(EVENTS.filter(e=>e.type).map(e=>JSON.parse(JSON.stringify(e)))).slice(0,5);
  state.deck=Array.from({length:5},(_,day)=>shuffle([questions[day*2],questions[day*2+1],miniGames[day]])).flat();
  state.index=0;state.log=[];state.eventFailures=0;state.resolving=false;state.standalone=false;state.standaloneEventId=null;state.sequenceProgress=[];state.collectHits=0;state.signatureHits=0;
  state.chat=[['Миша','Запускаем ООО. Коллеги, всем хорошего дня!'],['Родион','По 500 рублей на капитал, договорились?'],['Саша','Кто сегодня отвечает за документы?']];
  intro.classList.add('hidden');$('#mini-gallery').classList.add('hidden');ending.classList.add('hidden');game.classList.remove('hidden');$('#mini-arcade-nav').classList.add('hidden');$('#event-log').innerHTML='<li class="muted-log">Пока всё под контролем.</li>';renderMeters();renderChat();showEvent();
}
function renderMiniGallery(){const games=EVENTS.filter(event=>event.type&&event.id!=='misha-gift');$('#mini-gallery-list').innerHTML=games.map(event=>`<article class="mini-gallery-card"><span class="category-chip">${escapeHtml(event.category)}</span><h2>${escapeHtml(event.title)}</h2><p>${escapeHtml(event.description)}</p><button class="button button-primary" type="button" data-mini-play="${escapeHtml(event.id)}">ИГРАТЬ ↗</button></article>`).join('')}
function showMiniGallery(){clearMiniTimers();state.resolving=true;state.sequenceDrag=null;schedulePointer=null;document.querySelector('.sequence-drag-ghost')?.remove();document.querySelector('.schedule-drag-ghost')?.remove();$('#event-content').innerHTML='';intro.classList.add('hidden');game.classList.add('hidden');ending.classList.add('hidden');$('#mini-arcade-nav').classList.add('hidden');$('#mini-gallery').classList.remove('hidden');renderMiniGallery()}
function startStandaloneMini(eventId){const event=EVENTS.find(item=>item.id===eventId&&item.type&&item.id!=='misha-gift');if(!event)return;clearMiniTimers();state.stats={...START_STATS};state.deck=[JSON.parse(JSON.stringify(event))];state.index=0;state.log=[];state.chat=[['Тренировка','Выбрана отдельная миниигра.']];state.eventFailures=0;state.resolving=false;state.standalone=true;state.standaloneEventId=event.id;state.sequenceProgress=[];state.collectHits=0;state.signatureHits=0;intro.classList.add('hidden');$('#mini-gallery').classList.add('hidden');ending.classList.add('hidden');game.classList.remove('hidden');$('#mini-arcade-nav').classList.remove('hidden');$('#game-kicker').textContent='ОТДЕЛЬНЫЙ РЕЖИМ';$('#game-title').textContent=event.title;$('#day-number').textContent='ТРЕНИРОВКА';$('#day-name').textContent='Отдельная игра';$('#event-log').innerHTML='<li class="muted-log">Результаты не влияют на основной запуск.</li>';renderMeters();renderChat();showEvent()}
function renderMeters(){
  $('#meters').innerHTML=STAT_META.map(m=>`<div class="meter" data-key="${m.key}"><div class="meter-head"><span>${m.icon} &nbsp;${m.label}</span><span class="meter-value">${state.stats[m.key]}</span></div><div class="meter-track"><div class="meter-fill" style="width:${state.stats[m.key]}%"></div></div></div>`).join('');
}
function renderChat(newMessage){
  $('#chat-stream').innerHTML=state.chat.slice(-8).map(([name,msg],i)=>`<div class="chat-message ${newMessage&&i===state.chat.slice(-8).length-1?'new':''}"><span class="sender">${escapeHtml(name)}</span>${escapeHtml(msg)}</div>`).join('');
  $('#chat-stream').scrollTop=$('#chat-stream').scrollHeight;$('#unread-count').textContent=String(Math.min(9,Math.max(1,Math.floor(Math.random()*5)+1)));
}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function clearMiniTimers(){if(state.collectTimer){clearInterval(state.collectTimer);state.collectTimer=null}state.pizzaActive=false;if(state.pizzaFrame){cancelAnimationFrame(state.pizzaFrame);state.pizzaFrame=null}document.removeEventListener('keydown',handlePizzaKey)}
function prepareScenario(e){
  if(e.type==='sort'&&!e.scenarioPrepared){const s=drawUnseen('ooo-doc-scenarios-v1',DOC_SCENARIOS);e.title=s.title;e.description='Разложи три документа по стопкам: подписать, отправить или уточнить.';e.documents=s.documents;e.scenarioPrepared=true;e.tip='Эти документы ещё не попадались в нескольких последних запусках.';e.chat=[['Диадок','Новая пачка документов уже во входящих.'],['Коллега',s.documents[2][0]+' — это куда?']]}
  if(e.type==='find'&&!e.scenarioPrepared){const s=drawUnseen('ooo-message-scenarios-v1',MESSAGE_SCENARIOS);e.title=s.title;e.description=s.description;e.chat=s.chat;e.tip='Отметь ровно два важных сообщения. Уже показанные ситуации возвращаются только после просмотра всей колоды.';const mixed=shuffle([...s.correct.map(text=>({text,correct:true})),...s.distractors.map(text=>({text,correct:false}))]);e.items=mixed.map(item=>item.text);e.targets=mixed.flatMap((item,i)=>item.correct?[i]:[]);e.scenarioPrepared=true}
}
function showEvent(){
  const e=state.deck[state.index];if(!e){finishGame();return}
  state.sequenceProgress=[];prepareScenario(e);
  if(state.standalone){$('#game-kicker').textContent='ОТДЕЛЬНЫЙ РЕЖИМ';$('#game-title').textContent=e.title;$('#day-number').textContent='ТРЕНИРОВКА';$('#day-name').textContent='Отдельная игра';$('#event-count').textContent='МИНИИГРА'}else{const day=Math.floor(state.index/3);$('#game-kicker').textContent='ПЯТЬ ДНЕЙ ДО ЗАПУСКА';$('#game-title').textContent='Рабочая неделя';$('#day-number').textContent=`ДЕНЬ ${day+1}`;$('#day-name').textContent=DAYS[day];$('#event-count').textContent=`СОБЫТИЕ ${String(state.index+1).padStart(2,'0')} / 15`}
  $('#event-category').textContent=e.category;$('#event-tip').textContent=e.type?'Успех миниигры повышает показатели. Ошибка не отнимает очки; пропуск отнимает по 5 очков у капитала, фокуса и команды.':e.tip||'Каждое решение меняет общий баланс.';
  $('#progress-track').textContent=state.standalone?'ОТДЕЛЬНОЕ ПРОХОЖДЕНИЕ':`${'▰'.repeat(state.index)}${'▱'.repeat(15-state.index)} ${Math.round(state.index/15*100)}%`;
  const introHtml=`<h2 class="event-title">${e.title}</h2><p class="event-description">${e.description}</p>`;
  let body='';
  if(e.type==='collect')body=renderCollect(e);
  else if(e.type==='sort')body=renderSort(e);
  else if(e.type==='sequence')body=renderSequence(e);
  else if(e.type==='find')body=renderFind(e);
  else if(e.type==='flying-signatures')body=renderFlyingSignatures(e);
  else if(e.type==='pizza-run')body=renderPizzaRun();
  else if(e.type==='seal-search')body=renderSealSearch();
  else if(e.type==='misha-gift')body=renderMishaGift();
  else if(e.type==='schedule')body=renderSchedule(e);
  else if(e.type==='wire-puzzle')body=renderWirePuzzle();
  else body=renderChoices(e);
  $('#event-content').innerHTML=introHtml+`<div class="event-content">${body}${e.type?renderMiniSkip():''}</div>`;
  if(e.type==='collect')startContributionMini(e);
  if(e.type==='flying-signatures')startSignatureMini(e);
  if(e.type==='pizza-run')startPizzaRun(e);
  const chat=e.chat||[CHAT_FLAVOR[state.index%CHAT_FLAVOR.length]];state.chat.push(...chat);renderChat(true);
}
function normalizeEffects(effects={}){const visible={cash:effects.cash||0,focus:effects.focus||0,team:effects.team||0};if(effects.docs)visible.focus+=Math.round(effects.docs*.55);return visible}
function formatChoiceEffects(effects){const visible=normalizeEffects(effects);return STAT_META.filter(m=>visible[m.key]).map(m=>`${visible[m.key]>0?'+':'−'}${m.label.toLowerCase()} ${Math.abs(visible[m.key])}`).join(' · ')||'без изменений'}
function renderChoices(e){return `<div class="choice-grid">${e.choices.map((c,i)=>`<button class="choice-button" data-choice="${i}">${c[0]}<span class="choice-hint">${c[1]}</span><span class="choice-effects">${formatChoiceEffects(c[2])}</span></button>`).join('')}</div>`}
function renderCollect(e){return `<div class="micro-wrap"><p class="micro-instruction">НАЖМИ НА «500 ₽» ЗА 1 СЕКУНДУ</p><p class="micro-progress">ПОЙМАНО: <span id="collect-count">0</span> / ${e.needed}</p><div class="collect-timer"><div id="collect-timer-fill" class="collect-timer-fill"></div></div><div class="collect-grid" id="collect-grid"></div><p class="micro-caption">Одна карточка — взнос. Остальные пять сбивают с толку.</p></div>`}
function renderFlyingSignatures(e){return `<div class="micro-wrap"><p class="micro-instruction">ПОПАДИ ПО ПЯТИ ЛЕТЯЩИМ ПОДПИСЯМ</p><p class="micro-progress">ПОЙМАНО: <span id="signature-count">0</span> / ${e.needed}</p><div class="signature-lane" id="signature-lane" aria-label="Летящие карточки с подписями"></div><p class="micro-caption">Лови карточки «ПОДПИСАЛ», не трать время на «ЩАС» и «УТОЧНЮ».</p></div>`}
function renderSealSearch(){sealTarget=Math.floor(Math.random()*SEAL_OBJECTS.length);sealAttempts=0;sealBusy=false;return `<div class="micro-wrap seal-hunt"><p class="micro-instruction">ОБЫЩИ ТРИ ПРЕДМЕТА И НАЙДИ ПЕЧАТЬ</p><p class="micro-progress">ПОПЫТКИ: <span id="seal-attempts">3</span> / 3</p><div class="seal-cards" role="group" aria-label="Шесть предметов, под которыми может быть печать">${SEAL_OBJECTS.map(([icon,name],i)=>`<button class="seal-card seal-card-${i}" type="button" data-seal-object="${i}" aria-label="Проверить: ${name}"><span class="seal-card-icon" aria-hidden="true">${icon}</span><span class="seal-card-name">${name}</span><span class="seal-card-action">ПРОВЕРИТЬ</span><span class="seal-card-reveal" aria-hidden="true">✦ ПЕЧАТЬ ✦</span></button>`).join('')}</div><p class="micro-caption" id="seal-status" role="status" aria-live="polite">Нажми на карточку: предмет приподнимется, и ты увидишь, есть ли под ним печать.</p></div>`}
function renderMishaGift(){return `<div class="misha-gift"><div class="misha-gift-icon" aria-hidden="true">🎁</div><p class="micro-instruction">МИША ДЕЛИТСЯ ХОРОШИМ НАСТРОЕНИЕМ</p><button class="micro-submit misha-thanks" id="misha-thanks" type="button">СПАСИБО, МИША ↗</button></div>`}
function renderMiniSkip(){return `<div class="mini-skip-wrap"><span>ПРОПУСК: −5 К КАЖДОМУ ПОКАЗАТЕЛЮ</span><button class="mini-skip-button" id="mini-skip" type="button">ПРОПУСТИТЬ МИНИИГРУ</button></div>`}
function renderSchedule(e){scheduleClients=shuffle(e.clients.map(client=>({...client})));scheduleAssignments=Array(e.slots.length).fill(null);schedulePointer=null;return `<div class="schedule-mini"><p class="micro-instruction">ПЕРЕТАЩИ ТРЁХ КЛИЕНТОВ В ЧЕТЫРЕ ОКНА</p><div class="schedule-board" id="schedule-board">${renderScheduleBoard(e)}</div><p class="micro-caption" id="schedule-status" role="status" aria-live="polite">Зажми карточку клиента и перетащи её в подходящее окно. Одно окно останется пустым.</p><button class="micro-submit" id="schedule-submit" disabled>ПРОВЕРИТЬ РАСПИСАНИЕ ↗</button></div>`}
function wireDirection(from,to){if(to[0]<from[0])return'N';if(to[0]>from[0])return'S';if(to[1]<from[1])return'W';return'E'}
function wireRotate(directions,turns){const order=['N','E','S','W'];return directions.map(direction=>order[(order.indexOf(direction)+turns)%4])}
function wireMakePath(){const rows=3,cols=3,start=[0,0],goal=[2,2],path=[start],visited=new Set(['0,0']);let attempts=0;function walk(cell){if(++attempts>4000||path.length>9)return false;if(cell[0]===goal[0]&&cell[1]===goal[1])return path.length===9;const neighbors=[[cell[0]-1,cell[1]],[cell[0]+1,cell[1]],[cell[0],cell[1]-1],[cell[0],cell[1]+1]].filter(([row,col])=>row>=0&&row<rows&&col>=0&&col<cols&&!visited.has(`${row},${col}`));for(const next of shuffle(neighbors)){const key=`${next[0]},${next[1]}`;visited.add(key);path.push(next);if(walk(next))return true;path.pop();visited.delete(key)}return false}if(walk(start))return path;return [[0,0],[0,1],[0,2],[1,2],[1,1],[1,0],[2,0],[2,1],[2,2]]}
function wirePortsForPath(path,index){const here=path[index],previous=index===0?null:path[index-1],next=index===path.length-1?null:path[index+1];return [previous?wireDirection(here,previous):'W',next?wireDirection(here,next):'E']}
function wireSvg(ports){const endPoints={N:'50 0',E:'100 50',S:'50 100',W:'0 50'},paths=ports.map(direction=>`M 50 50 L ${endPoints[direction]}`).join(' ');return `<svg viewBox="0 0 100 100" aria-hidden="true"><path class="wire-outline" d="${paths}"/><path class="wire-core" d="${paths}"/><circle cx="50" cy="50" r="7" class="wire-joint"/></svg>`}
function renderWirePuzzle(){const path=wireMakePath(),solution=Array(9).fill(null),tiles=Array(9).fill(null);path.forEach((cell,index)=>{const id=cell[0]*3+cell[1],ports=wirePortsForPath(path,index),scramble=ports[0]==='N'&&ports[1]==='S'||ports[0]==='S'&&ports[1]==='N'?shuffle([1,3])[0]:1+Math.floor(Math.random()*3);solution[id]=ports;tiles[id]={rotation:scramble,ports:wireRotate(ports,scramble),start:index===0,end:index===path.length-1}});wirePuzzle={path,solution,tiles};return `<div class="micro-wrap wire-mini"><p class="micro-instruction">СОЕДИНИ РОУТЕР С КОМПЬЮТЕРОМ ЧЕРЕЗ ВСЕ 9 КЛЕТОК</p><div class="wire-route-labels"><span>◉ РОУТЕР · СТАРТ</span><span>ФИНИШ · КОМПЬЮТЕР ▣</span></div><div class="wire-grid" id="wire-grid" role="group" aria-label="Поле из девяти кабельных сегментов: каждый входит в цепь от роутера к компьютеру">${renderWireGrid()}</div><p class="micro-progress wire-status" id="wire-status" role="status" aria-live="polite">СИГНАЛ: 0 / 9 КЛЕТОК</p><p class="micro-caption">Нажимай на кабель, чтобы повернуть его. Проложи непрерывный путь от углового роутера до компьютера по диагонали.</p></div>`}
function renderWireGrid(){return wirePuzzle.tiles.map((tile,index)=>tile?`<button class="wire-tile${tile.start?' wire-start':''}${tile.end?' wire-end':''}" type="button" data-wire-tile="${index}" aria-label="Повернуть кабельный сегмент${tile.start?' у роутера':''}${tile.end?' у компьютера':''}" style="--wire-turn:${tile.rotation*90}deg">${wireSvg(wirePuzzle.solution[index])}${tile.start?'<span class="wire-endpoint">◉</span>':''}${tile.end?'<span class="wire-endpoint">▣</span>':''}<span class="wire-turn-indicator">↻</span></button>`:'<div class="wire-empty" aria-hidden="true"></div>').join('')}
function rotateWireTile(index){const tile=wirePuzzle?.tiles[index];if(!tile||state.resolving)return;tile.rotation=(tile.rotation+1)%4;tile.ports=wireRotate(wirePuzzle.solution[index],tile.rotation);const button=document.querySelector(`[data-wire-tile="${index}"]`);button.style.setProperty('--wire-turn',`${tile.rotation*90}deg`);button.classList.add('wire-turning');setTimeout(()=>button.classList.remove('wire-turning'),160);$$('.wire-tile.wire-live').forEach(item=>item.classList.remove('wire-live'));const start=wirePuzzle.path[0],startId=start[0]*3+start[1];let connected=wirePuzzle.tiles[startId].ports.includes('W')?1:0;if(connected)document.querySelector(`[data-wire-tile="${startId}"]`)?.classList.add('wire-live');for(let i=0;i<wirePuzzle.path.length-1&&connected>0;i++){const from=wirePuzzle.path[i],to=wirePuzzle.path[i+1],fromId=from[0]*3+from[1],toId=to[0]*3+to[1],direction=wireDirection(from,to);if(wirePuzzle.tiles[fromId].ports.includes(direction)&&wirePuzzle.tiles[toId].ports.includes(wireDirection(to,from))){connected++;document.querySelector(`[data-wire-tile="${toId}"]`)?.classList.add('wire-live')}else break}$('#wire-status').textContent=`СИГНАЛ: ${connected} / ${wirePuzzle.path.length} КЛЕТОК`;const end=wirePuzzle.path[wirePuzzle.path.length-1],endId=end[0]*3+end[1];if(connected===wirePuzzle.path.length&&wirePuzzle.tiles[endId].ports.includes('E'))finishMini(state.deck[state.index],true,'Интернет восстановлен')}
function renderScheduleBoard(e){const placed=scheduleAssignments.filter(value=>value!==null);return `<section class="schedule-client-panel"><p class="schedule-section-label">КЛИЕНТЫ · ПЕРЕТАЩИ В ОКНО</p><div class="schedule-bank">${scheduleClients.map((client,i)=>placed.includes(i)?'':`<button class="schedule-client" type="button" data-schedule-client="${i}"><strong>${escapeHtml(client.name)}</strong><span>${escapeHtml(client.request)}</span></button>`).join('')}</div></section><section class="schedule-slot-panel"><p class="schedule-section-label">СВОБОДНЫЕ ОКНА</p><div class="schedule-slots">${e.slots.map((slot,i)=>{const clientIndex=scheduleAssignments[i];const client=clientIndex===null?null:scheduleClients[clientIndex];return `<div class="schedule-slot" data-schedule-slot="${i}"><strong class="schedule-time">${slot.time}</strong><span class="schedule-specialist">${slot.staff}</span>${client?`<button class="schedule-client schedule-client-placed" type="button" data-schedule-client="${clientIndex}"><strong>${escapeHtml(client.name)}</strong><span>${escapeHtml(client.request)}</span></button>`:'<span class="schedule-empty">ПЕРЕТАЩИ СЮДА</span>'}</div>`}).join('')}</div></section>`}
function updateScheduleBoard(){const e=state.deck[state.index];$('#schedule-board').innerHTML=renderScheduleBoard(e);$('#schedule-submit').disabled=scheduleAssignments.filter(value=>value!==null).length!==scheduleClients.length}
function assignScheduleClient(clientIndex,slotIndex){const oldSlot=scheduleAssignments.indexOf(clientIndex);if(oldSlot===slotIndex)return;const displaced=scheduleAssignments[slotIndex];if(oldSlot>=0)scheduleAssignments[oldSlot]=displaced;scheduleAssignments[slotIndex]=clientIndex;updateScheduleBoard();$('#schedule-status').textContent='Запись поставлена. Проверь время и специалиста для остальных клиентов.'}
function finishScheduleDrag(ev,cancelled=false){const drag=schedulePointer;if(!drag||drag.pointerId!==ev.pointerId)return;const target=cancelled?null:document.elementFromPoint(ev.clientX,ev.clientY)?.closest('[data-schedule-slot]');if(drag.moved&&!cancelled){if(target)assignScheduleClient(drag.clientIndex,Number(target.dataset.scheduleSlot));scheduleSuppressClickUntil=Date.now()+350}drag.element?.classList.remove('dragging');document.querySelector('.schedule-drag-ghost')?.remove();$$('.schedule-slot.drag-over').forEach(slot=>slot.classList.remove('drag-over'));schedulePointer=null}
function renderPizzaRun(){return `<div class="micro-wrap pizza-wrap"><p class="micro-instruction">ПРОБЕЛ / ↑ / ТАП — ПРЫЖОК</p><p class="micro-progress">КОРОБКИ: <span id="pizza-boxes" class="pizza-boxes" aria-label="Три коробки пиццы"><i>▣</i><i>▣</i><i>▣</i></span> <b id="pizza-box-count">3 / 3</b> <span class="pizza-distance">ДО ОФИСА: <b id="pizza-distance">100%</b></span></p><div class="pizza-track"><canvas id="pizza-canvas" width="720" height="240" aria-label="Курьер несёт три коробки пиццы через препятствия к офису"></canvas></div><button class="micro-submit pizza-jump" id="pizza-jump" type="button">ПРЫЖОК ↗</button><p class="micro-caption">Перепрыгивай камни и ямы. За 3 коробки — большая награда, за 2 — средняя, за 1 — небольшая.</p></div>`}
function startPizzaRun(e){state.pizzaActive=true;state.pizzaProgress=0;state.pizzaHits=0;state.pizzaBoxes=3;state.pizzaBlinkUntil=0;state.pizzaJumpStartedAt=-Infinity;state.pizzaLastFrame=0;state.pizzaObstacles=PIZZA_OBSTACLES.map(o=>({...o,hit:false}));document.addEventListener('keydown',handlePizzaKey);$('#pizza-canvas').addEventListener('pointerdown',pizzaJump);$('#pizza-jump').addEventListener('pointerdown',pizzaJump);state.pizzaFrame=requestAnimationFrame(now=>pizzaRunFrame(now,e))}
function handlePizzaKey(ev){if(!state.pizzaActive||state.resolving)return;if([' ','ArrowUp','w','W','ц','Ц'].includes(ev.key)){ev.preventDefault();pizzaJump()}}
function pizzaJump(){if(!state.pizzaActive||state.resolving)return;const elapsed=performance.now()-state.pizzaJumpStartedAt;if(elapsed>PIZZA_JUMP_MS)state.pizzaJumpStartedAt=performance.now()}
function pizzaRunFrame(now,e){if(!state.pizzaActive||state.resolving)return;const dt=state.pizzaLastFrame?Math.min(.04,(now-state.pizzaLastFrame)/1000):0;state.pizzaLastFrame=now;const speed=205+Math.min(65,state.pizzaProgress/45);state.pizzaProgress+=speed*dt;const jumpElapsed=now-state.pizzaJumpStartedAt;const jumpT=jumpElapsed<PIZZA_JUMP_MS?Math.max(0,jumpElapsed/PIZZA_JUMP_MS):1;const jumpHeight=jumpT<1?Math.sin(jumpT*Math.PI)*63:0;
  state.pizzaObstacles.forEach(obstacle=>{if(state.resolving)return;const x=PIZZA_PLAYER_X+obstacle.distance-state.pizzaProgress;if(!obstacle.hit&&x<PIZZA_PLAYER_X+34&&x+obstacle.width>PIZZA_PLAYER_X+8){obstacle.hit=true;if(jumpHeight<31){state.pizzaHits++;state.pizzaBoxes=Math.max(0,3-state.pizzaHits);state.pizzaBlinkUntil=now+1150;$('#pizza-boxes').innerHTML=Array.from({length:3},(_,i)=>`<i class="${i<state.pizzaBoxes?'':'lost'}">▣</i>`).join('');const noun=state.pizzaBoxes===1?'Осталась 1 коробка пиццы':`Осталось ${state.pizzaBoxes} ${state.pizzaBoxes===2?'коробки':'коробок'} пиццы`;$('#pizza-boxes').setAttribute('aria-label',noun);$('#pizza-box-count').textContent=`${state.pizzaBoxes} / 3`;const track=$('.pizza-track');track.classList.remove('damage-flash');void track.offsetWidth;track.classList.add('damage-flash');setTimeout(()=>track.classList.remove('damage-flash'),600);if(state.pizzaBoxes===0){finishMini(e,false,'Все коробки пиццы потеряны');return}}}});
  if(state.resolving)return;drawPizzaScene(now,jumpHeight);$('#pizza-distance').textContent=`${Math.max(0,Math.ceil((1-state.pizzaProgress/PIZZA_FINISH)*100))}%`;if(state.pizzaProgress>=PIZZA_FINISH){const rewards={3:{cash:10,focus:18,team:20},2:{cash:7,focus:12,team:13},1:{cash:5,focus:6,team:7}};const bonus=miniRewardEffects(rewards[state.pizzaBoxes]);const notes={3:'Все коробки на месте.',2:'Две коробки доехали целыми.',1:'Доехала только одна коробка.'};resolveEvent(`Доставлено коробок: ${state.pizzaBoxes} из 3`,bonus,true,`${notes[state.pizzaBoxes]} Награда: ${miniRewardSummary(bonus)}.`,true,bonus);return}state.pizzaFrame=requestAnimationFrame(next=>pizzaRunFrame(next,e))}
function drawPizzaScene(now,jumpHeight){const canvas=$('#pizza-canvas');if(!canvas)return;const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height,ground=PIZZA_GROUND_Y;ctx.clearRect(0,0,w,h);ctx.fillStyle='#d9e8d0';ctx.fillRect(0,0,w,h);ctx.fillStyle='#b8d6cc';ctx.fillRect(0,0,w,130);ctx.fillStyle='#f5d76c';ctx.fillRect(604,27,38,38);ctx.fillStyle='#8aaf9f';for(let i=0;i<8;i++){const bw=42+(i%3)*16,bh=44+(i%4)*13,x=((i*112-state.pizzaProgress*.22)%850+850)%850-70;ctx.fillRect(x,ground-bh-6,bw,bh);ctx.fillStyle='#d5e3d2';for(let wx=x+8;wx<x+bw-5;wx+=15)ctx.fillRect(wx,ground-bh+8,6,8);ctx.fillStyle='#8aaf9f'}
  ctx.fillStyle='#6a9b6a';ctx.fillRect(0,ground,w,52);ctx.fillStyle='#426c4c';ctx.fillRect(0,ground,w,5);ctx.fillStyle='#d1d09a';ctx.fillRect(0,ground+7,w,2);
  // A distant office marks the finish.
  const officeX=Math.min(660,PIZZA_PLAYER_X+PIZZA_FINISH-state.pizzaProgress);ctx.fillStyle='#db9b61';ctx.fillRect(officeX,79,80,109);ctx.fillStyle='#293d37';ctx.fillRect(officeX-5,73,90,10);ctx.fillStyle='#f4eed5';ctx.fillRect(officeX+13,91,54,17);ctx.fillStyle='#334a41';ctx.font='bold 9px monospace';ctx.fillText('ОФИС',officeX+21,103);ctx.fillStyle='#78b8c4';ctx.fillRect(officeX+12,116,18,19);ctx.fillRect(officeX+49,116,18,19);ctx.fillStyle='#805442';ctx.fillRect(officeX+33,145,17,43);
  state.pizzaObstacles.forEach(o=>{const x=PIZZA_PLAYER_X+o.distance-state.pizzaProgress;if(x<-80||x>w+180)return;if(o.type==='rock'){ctx.fillStyle='#687a70';ctx.fillRect(x,ground-23,o.width,23);ctx.fillStyle='#89998b';ctx.fillRect(x+6,ground-28,18,7);ctx.fillStyle='#394e43';ctx.fillRect(x+4,ground-5,o.width-7,5)}else{
    // The gap reads as a cut in the ground, with water filling its lower half.
    ctx.fillStyle='#4d5945';ctx.fillRect(x,ground-1,o.width,45);
    ctx.fillStyle='#253a34';ctx.fillRect(x+5,ground+4,o.width-10,38);
    ctx.fillStyle='#8cb492';ctx.fillRect(x-4,ground-3,o.width+8,5);
    ctx.fillStyle='#6bb4bd';ctx.fillRect(x+6,ground+22,o.width-12,18);
    ctx.fillStyle='#a6d8d2';ctx.fillRect(x+10,ground+22,o.width-20,3);
    ctx.fillStyle='#397f8d';ctx.fillRect(x+8,ground+34,o.width-16,3);
  }});
  // Pixel courier carrying three pizza boxes.
  const py=ground-42-jumpHeight,bob=jumpHeight?0:Math.sin(now/90)*2;ctx.globalAlpha=now<state.pizzaBlinkUntil&&Math.floor(now/95)%2===0?.18:1;ctx.fillStyle='#253b36';ctx.fillRect(PIZZA_PLAYER_X+6,py+3+bob,23,25);ctx.fillStyle='#e4b28d';ctx.fillRect(PIZZA_PLAYER_X+9,py-9+bob,18,17);ctx.fillStyle='#503f35';ctx.fillRect(PIZZA_PLAYER_X+8,py-12+bob,20,7);ctx.fillStyle='#739abe';ctx.fillRect(PIZZA_PLAYER_X+5,py+19+bob,24,18);ctx.fillStyle='#df9a68';ctx.fillRect(PIZZA_PLAYER_X+25,py+17+bob,13,6);for(let box=0;box<state.pizzaBoxes;box++){const bx=PIZZA_PLAYER_X+31,by=py+2+bob+(3-state.pizzaBoxes+box)*12;ctx.fillStyle=box%2?'#f5dfa5':'#fff0c9';ctx.fillRect(bx,by,25,11);ctx.fillStyle='#c96f50';ctx.fillRect(bx,by,25,3);ctx.fillStyle='#a95742';ctx.fillRect(bx+7,by+5,4,3);ctx.fillRect(bx+17,by+4,4,3);ctx.fillStyle='#8f5b43';ctx.fillRect(bx,by+9,25,2)}ctx.fillStyle='#263b35';ctx.fillRect(PIZZA_PLAYER_X+8,py+37+bob,8,9);ctx.fillRect(PIZZA_PLAYER_X+21,py+37+bob,8,9);ctx.fillStyle='#f3eedb';ctx.fillRect(PIZZA_PLAYER_X+5,py+44+bob,12,5);ctx.fillRect(PIZZA_PLAYER_X+19,py+44+bob,13,5);ctx.globalAlpha=1;
}
function renderSort(e){return `<div class="micro-wrap"><p class="micro-instruction">НАЖИМАЙ НА КАРТОЧКУ, ЧТОБЫ СМЕНИТЬ СТОПКУ</p><div class="sort-grid">${e.documents.map((d,i)=>`<button class="sort-card" data-doc="${i}" data-bucket="-1">${escapeHtml(d[0])}<strong>НЕ РАЗОБРАНО</strong></button>`).join('')}</div><button class="micro-submit" id="sort-submit">ПРОВЕРИТЬ ДОКУМЕНТЫ ↗</button></div>`}
function renderSequence(e){state.sequencePlaced=Array(e.sequence.length).fill(null);state.sequenceAvailable=shuffle(e.sequence);state.sequenceSelected=null;return `<div class="micro-wrap"><p class="micro-instruction">ПЕРЕТАЩИ ШАГИ В ПЯТЬ ОКОШЕК ИЛИ НАЖМИ КАРТОЧКУ, А ЗАТЕМ ОКОШКО</p><div id="sequence-board">${renderSequenceBoard(e)}</div><p class="micro-progress" id="sequence-progress">ЗАПОЛНЕНО: 0 / ${e.sequence.length}</p><button class="micro-submit" id="sequence-submit" disabled>ПРОВЕРИТЬ ПОРЯДОК ↗</button></div>`}
function renderSequenceBoard(e){return `<div class="sequence-slots">${state.sequencePlaced.map((value,i)=>`<div class="sequence-slot ${value?'filled':''}" data-slot="${i}"><span class="slot-number">${i+1}</span>${value?`<span class="slot-value" data-sequence-source="slot" data-slot="${i}">${escapeHtml(value)}</span>`:'<span class="slot-placeholder">ПЕРЕТАЩИ СЮДА</span>'}</div>`).join('')}</div><div class="sequence-buttons" data-sequence-bank aria-label="Перемешанные шаги">${state.sequenceAvailable.map(value=>`<button class="sequence-card ${state.sequenceSelected===value?'selected':''}" data-sequence-source="bank" data-seq="${escapeHtml(value)}">${escapeHtml(value)}</button>`).join('')}</div>`}
function updateSequenceBoard(){const e=state.deck[state.index];$('#sequence-board').innerHTML=renderSequenceBoard(e);const count=state.sequencePlaced.filter(Boolean).length;$('#sequence-progress').textContent=`ЗАПОЛНЕНО: ${count} / ${e.sequence.length}`;$('#sequence-submit').disabled=count!==e.sequence.length}
function placeSequenceValue(value,slotIndex,sourceSlot=null){if(state.resolving)return;if(sourceSlot!==null){if(sourceSlot===slotIndex)return;const displaced=state.sequencePlaced[slotIndex];state.sequencePlaced[slotIndex]=value;state.sequencePlaced[sourceSlot]=displaced||null}else{const displaced=state.sequencePlaced[slotIndex];if(displaced)state.sequenceAvailable.push(displaced);state.sequenceAvailable=state.sequenceAvailable.filter(v=>v!==value);state.sequencePlaced[slotIndex]=value}state.sequenceSelected=null;updateSequenceBoard()}
function clearSequenceSlot(slotIndex){const value=state.sequencePlaced[slotIndex];if(!value)return;state.sequencePlaced[slotIndex]=null;state.sequenceAvailable.push(value);state.sequenceSelected=null;updateSequenceBoard()}
function renderFind(e){return `<div class="micro-wrap"><p class="micro-instruction">НАЙДИ ОБА СООБЩЕНИЯ, КОТОРЫЕ ПОМОГУТ СЕГОДНЯ</p><div class="find-grid">${e.items.map((s,i)=>`<button class="find-item" data-find="${i}">${escapeHtml(s)}</button>`).join('')}</div><p class="micro-progress">ОТМЕЧЕНО: <span id="find-count">0</span> / 2</p><button class="micro-submit" id="find-submit">ПЕРЕДАТЬ СВОДКУ ↗</button></div>`}
function startContributionMini(e){
  state.collectHits=0;refreshContributionRound(e);
  state.collectTimer=setInterval(()=>{if(!state.resolving)refreshContributionRound(e)},1000);
}
function refreshContributionRound(e){
  state.collectRoundSuccess=false;$('#collect-count').textContent=state.collectHits;
  const decoys=shuffle(['скриншот','я потом','перевёл?','уточню у бухгалтера','завтра скину']).slice(0,5);
  const cards=shuffle(['500 ₽',...decoys]);
  $('#collect-grid').innerHTML=cards.map((text,i)=>`<button class="contribution-card" data-token="${text==='500 ₽'}">${escapeHtml(text)}</button>`).join('');
}
function startSignatureMini(e){
  state.signatureHits=0;$('#signature-count').textContent='0';
  const lane=$('#signature-lane');const cards=shuffle([true,true,true,true,true,false,false,false,false,false]);
  cards.forEach(valid=>spawnSignatureCard(valid));
}
function spawnSignatureCard(valid){
  const lane=$('#signature-lane');if(!lane||state.resolving)return;
  const card=document.createElement('button');card.className=`flying-card ${valid?'signature-card':'decoy-card'}`;card.dataset.signature=String(valid);card.textContent=valid?'ПОДПИСАЛ':['ЩАС','УТОЧНЮ','ПОЗЖЕ'][Math.floor(Math.random()*3)];
  card.style.setProperty('--fly-y',`${8+Math.random()*72}%`);card.style.setProperty('--fly-duration',`${4.7+Math.random()*2.3}s`);card.style.setProperty('--fly-delay',`${-Math.random()*4}s`);
  card.addEventListener('animationend',()=>{if(!card.isConnected||state.resolving)return;card.remove();spawnSignatureCard(valid)});
  lane.append(card);
}
function resolveEvent(title,effects,success,extra,miniResult=false,reward={}){
  if(state.resolving)return;state.resolving=true;
  clearMiniTimers();
  const appliedEffects=normalizeEffects(effects);Object.keys(state.stats).forEach(k=>state.stats[k]=Math.max(0,Math.min(100,state.stats[k]+(appliedEffects[k]||0))));
  if(!success)state.eventFailures++;
  state.log.push({title,success,extra});$('#event-log').innerHTML=state.log.slice(-8).map(x=>`<li>${x.success?'✓':'!'} ${escapeHtml(x.title)}${x.extra?` — ${escapeHtml(x.extra)}`:''}</li>`).join('');
  renderMeters();
  if(miniResult){
    state.pendingMiniCrash=!state.standalone&&Object.values(state.stats).some(v=>v<=0);
    setTimeout(()=>{state.resolving=false;renderMiniResult(title,success,extra,reward,state.standalone)},220);
    return;
  }
  if(state.standalone){setTimeout(()=>{state.resolving=false;renderMiniResult(title,success,extra,{},true)},220);return}
  if(Object.values(state.stats).some(v=>v<=0)){finishGame(true);return}
  state.index++;setTimeout(()=>{state.resolving=false;showEvent()},220);
}
function renderMiniResult(title,success,extra,reward,standalone){
  const detail=success?miniRewardSummary(reward):extra||'Награды нет, показатели не изменились.';
  const action=standalone
    ?'<button id="mini-replay" class="button button-primary" type="button">СЫГРАТЬ ЕЩЁ ↗</button><button id="mini-result-list" class="button button-secondary" type="button">К СПИСКУ МИНИИГР</button>'
    :'<button id="mini-continue" class="button button-primary" type="button">ПРОДОЛЖИТЬ ↗</button>';
  $('#event-content').innerHTML=`<div class="standalone-result mini-result"><span class="ending-stamp ${success?'standalone-success':'standalone-skip'}">${success?'ПОБЕДА':'БЕЗ НАГРАДЫ'}</span><p class="eyebrow">ИТОГ МИНИИГРЫ</p><h2>${success?'Ты выиграл!':'В этот раз не получилось'}</h2><p class="mini-result-title">${escapeHtml(title)}</p><div class="mini-result-reward"><strong>${success?'ТЫ ПОЛУЧИЛ':'ТЫ НЕ ПОЛУЧИЛ НАГРАДУ'}</strong><span>${escapeHtml(detail)}</span></div>${standalone?'<p class="standalone-note">Это отдельное прохождение. Показатели и результат не влияют на основную игру.</p>':''}<div class="standalone-result-actions">${action}</div></div>`;
  $('#event-count').textContent='РЕЗУЛЬТАТ';$('#event-tip').textContent=standalone?'Выбери эту игру ещё раз или вернись к списку миниигр.':'Посмотри результат, затем продолжай рабочий день.';
}
function handleChoice(button){const e=state.deck[state.index],choice=e.choices[Number(button.dataset.choice)];resolveEvent(choice[0],choice[2],true,choice[1]);}
function miniRewardEffects(effects={}){const reward=normalizeEffects(effects);return Object.fromEntries(STAT_META.map(({key})=>[key,Math.max(5,reward[key]||0)]))}
function miniRewardSummary(reward){return STAT_META.map(({key,label})=>`${label.toLowerCase()} +${reward[key]}`).join(', ')}
function finishMini(e,success,title){const reward=success?miniRewardEffects(e.success):{};const detail=success?'Награда начислена по всем трём показателям.':'Награды нет, показатели не изменились.';resolveEvent(title||e.title,reward,success,detail,true,reward);}
function updateSequenceDragTarget(x,y){$$('.sequence-slot.drag-over').forEach(slot=>slot.classList.remove('drag-over'));const target=document.elementFromPoint(x,y)?.closest('[data-slot]');if(target)target.classList.add('drag-over');return target}
function finishSequenceDrag(ev,cancelled=false){const drag=state.sequenceDrag;if(!drag||drag.pointerId!==ev.pointerId)return;const target=cancelled?null:updateSequenceDragTarget(ev.clientX,ev.clientY);if(drag.moved&&!cancelled){if(target)placeSequenceValue(drag.value,Number(target.dataset.slot),drag.sourceSlot);else if(drag.sourceSlot!==null&&document.elementFromPoint(ev.clientX,ev.clientY)?.closest('[data-sequence-bank]'))clearSequenceSlot(drag.sourceSlot);state.sequenceSuppressClickUntil=Date.now()+350}drag.sourceElement?.classList.remove('dragging');document.querySelector('.sequence-drag-ghost')?.remove();$$('.sequence-slot.drag-over').forEach(slot=>slot.classList.remove('drag-over'));state.sequenceDrag=null}
document.addEventListener('pointerdown',ev=>{const source=ev.target.closest('[data-sequence-source]');if(!source||state.resolving)return;const sourceSlot=source.dataset.sequenceSource==='slot'?Number(source.dataset.slot):null;state.sequenceDrag={value:source.dataset.seq||source.textContent.trim(),sourceSlot,pointerId:ev.pointerId,startX:ev.clientX,startY:ev.clientY,moved:false,sourceElement:source};source.classList.add('dragging');const ghost=document.createElement('div');ghost.className='sequence-drag-ghost';ghost.textContent=state.sequenceDrag.value;ghost.style.left=`${ev.clientX+12}px`;ghost.style.top=`${ev.clientY+12}px`;document.body.append(ghost)});
document.addEventListener('pointermove',ev=>{const drag=state.sequenceDrag;if(!drag||drag.pointerId!==ev.pointerId)return;if(Math.abs(ev.clientX-drag.startX)+Math.abs(ev.clientY-drag.startY)>8)drag.moved=true;const ghost=document.querySelector('.sequence-drag-ghost');if(ghost){ghost.style.left=`${ev.clientX+12}px`;ghost.style.top=`${ev.clientY+12}px`}if(drag.moved)updateSequenceDragTarget(ev.clientX,ev.clientY)});
document.addEventListener('pointerup',ev=>finishSequenceDrag(ev));document.addEventListener('pointercancel',ev=>finishSequenceDrag(ev,true));
document.addEventListener('pointerdown',ev=>{const client=ev.target.closest('[data-schedule-client]');if(!client||state.resolving)return;ev.preventDefault();schedulePointer={clientIndex:Number(client.dataset.scheduleClient),pointerId:ev.pointerId,startX:ev.clientX,startY:ev.clientY,moved:false,element:client};client.classList.add('dragging');const ghost=document.createElement('div');ghost.className='schedule-drag-ghost';ghost.textContent=client.innerText.replace(/\s+/g,' ').trim();ghost.style.left=`${ev.clientX+12}px`;ghost.style.top=`${ev.clientY+12}px`;document.body.append(ghost)});
document.addEventListener('pointermove',ev=>{const drag=schedulePointer;if(!drag||drag.pointerId!==ev.pointerId)return;if(Math.abs(ev.clientX-drag.startX)+Math.abs(ev.clientY-drag.startY)>8)drag.moved=true;const ghost=document.querySelector('.schedule-drag-ghost');if(ghost){ghost.style.left=`${ev.clientX+12}px`;ghost.style.top=`${ev.clientY+12}px`}$$('.schedule-slot.drag-over').forEach(slot=>slot.classList.remove('drag-over'));if(drag.moved){const target=document.elementFromPoint(ev.clientX,ev.clientY)?.closest('[data-schedule-slot]');if(target)target.classList.add('drag-over')}});
document.addEventListener('pointerup',ev=>finishScheduleDrag(ev));document.addEventListener('pointercancel',ev=>finishScheduleDrag(ev,true));
function finishGame(crashed=false){
  clearMiniTimers();
  game.classList.add('hidden');ending.classList.remove('hidden');$('#recap').classList.add('hidden');
  const score=Object.values(state.stats).reduce((a,b)=>a+b,0);const launched=!crashed&&score>=MIN_LAUNCH_SCORE;
  $('#ending-stamp').textContent=crashed?'АВАРИЙНЫЙ ВЫХОД':launched?'ЗАПУЩЕНО':'ПЕРЕНОС ЗАПУСКА';$('#ending-stamp').style.color=crashed?'#b44d40':'#518253';$('#ending-stamp').style.borderColor=crashed?'#b44d40':'#518253';
  const zeroStats=STAT_META.filter(m=>state.stats[m.key]<=0).map(m=>m.label.toLowerCase());
  $('#ending-title').textContent=crashed?'Запуск остановлен':launched?'Компания работает!':'Не хватило очков до запуска';
  $('#ending-copy').textContent=crashed?`Показатель «${zeroStats.join('» и «')}» опустился до нуля. Для запуска нужно сохранить все три показателя выше нуля и набрать минимум ${MIN_LAUNCH_SCORE} очков суммарно.`:launched?`Ты набрал ${score} очков из необходимых ${MIN_LAUNCH_SCORE}. Все три показателя остались выше нуля — компания запущена.`:`Ты набрал ${score} из необходимых ${MIN_LAUNCH_SCORE} очков. Не хватило ${MIN_LAUNCH_SCORE-score}. Сохрани все три показателя выше нуля и набери нужную сумму.`;
  $('#final-stats').innerHTML=STAT_META.map(m=>`<div class="final-stat"><strong>${state.stats[m.key]}</strong>${m.label}</div>`).join('')+`<div class="final-stat"><strong>${score} / ${MIN_LAUNCH_SCORE}</strong>ОЧКИ ВСЕГО</div>`;
  $('#recap').innerHTML=`<strong>ЖУРНАЛ ЗАПУСКА</strong><br>${state.log.map((x,i)=>`${String(i+1).padStart(2,'0')}. ${x.success?'✓':'!'} ${escapeHtml(x.title)}${x.extra?` — ${escapeHtml(x.extra)}`:''}`).join('<br>')}`;
}
$('#start-button').addEventListener('click',startGame);$('#mini-gallery-open').addEventListener('click',showMiniGallery);$('#mini-gallery-home').addEventListener('click',()=>{state.resolving=false;$('#mini-gallery').classList.add('hidden');intro.classList.remove('hidden')});$('#mini-arcade-back').addEventListener('click',showMiniGallery);$('#again-button').addEventListener('click',startGame);$('#recap-button').addEventListener('click',()=>$('#recap').classList.toggle('hidden'));
document.addEventListener('click',ev=>{
  const miniPlay=ev.target.closest('[data-mini-play]');if(miniPlay){startStandaloneMini(miniPlay.dataset.miniPlay);return}
  if(ev.target.closest('#mini-continue')){const crashed=state.pendingMiniCrash;state.pendingMiniCrash=false;if(crashed){finishGame(true)}else{state.index++;state.resolving=false;showEvent()}return}
  if(ev.target.closest('#mini-replay')){startStandaloneMini(state.standaloneEventId);return}
  if(ev.target.closest('#mini-result-list')){showMiniGallery();return}
  if(ev.target.closest('#mini-skip')){resolveEvent('Миниигра пропущена',{cash:-5,focus:-5,team:-5},false,'Штраф за пропуск: капитал −5, фокус −5, команда −5.',true,{});return}
  if(ev.target.closest('#misha-thanks')){finishMini(state.deck[state.index],true,'Подгон от Миши принят');return}
  const wireTile=ev.target.closest('[data-wire-tile]');if(wireTile){rotateWireTile(Number(wireTile.dataset.wireTile));return}
  const scheduleClient=ev.target.closest('[data-schedule-client]');if(scheduleClient){if(state.resolving||Date.now()<scheduleSuppressClickUntil)return;$('#schedule-status').textContent='Зажми карточку и перетащи её в подходящее окно.';return}
  const scheduleSlot=ev.target.closest('[data-schedule-slot]');if(scheduleSlot){if(state.resolving||Date.now()<scheduleSuppressClickUntil)return;$('#schedule-status').textContent='Перетащи сюда карточку клиента.';return}
  if(ev.target.closest('#schedule-submit')){const e=state.deck[state.index];const good=scheduleClients.every((client,index)=>scheduleAssignments[client.slot]===index);finishMini(e,good,good?'Расписание собрано без ошибок':'В расписании есть ошибка');return}
  const sealObject=ev.target.closest('[data-seal-object]');if(sealObject){if(state.resolving||sealBusy||sealObject.disabled)return;sealBusy=true;sealObject.disabled=true;sealObject.classList.add('lifting');setTimeout(()=>{if(!sealObject.isConnected||state.resolving)return;sealObject.classList.remove('lifting');sealAttempts++;const remaining=3-sealAttempts;$('#seal-attempts').textContent=remaining;if(Number(sealObject.dataset.sealObject)===sealTarget){sealObject.classList.add('found');$('#seal-status').textContent='Нашёл! Печать сияет под предметом.';setTimeout(()=>finishMini(state.deck[state.index],true,'Печать найдена'),850);return}sealObject.classList.add('searched');if(remaining===0){$('#seal-status').textContent='Здесь пусто. Попытки закончились.';setTimeout(()=>finishMini(state.deck[state.index],false,'Печать не найдена'),500)}else{$('#seal-status').textContent=`Здесь пусто. Осталось попыток: ${remaining}.`;setTimeout(()=>{sealBusy=false},300)}},300+SEAL_LIFT_HOLD_MS);return}
  const choice=ev.target.closest('[data-choice]');if(choice){handleChoice(choice);return}
  const token=ev.target.closest('[data-token]');if(token){if(state.resolving||state.collectRoundSuccess)return;if(token.dataset.token==='true'){state.collectRoundSuccess=true;state.collectHits++;token.classList.add('card-hit');$$('.contribution-card').forEach(card=>card.disabled=true);$('#collect-count').textContent=state.collectHits;if(state.collectHits>=5)finishMini(state.deck[state.index],true,'Пять взносов собраны')}else{token.disabled=true;token.classList.add('card-miss')}return}
  const flying=ev.target.closest('[data-signature]');if(flying){if(state.resolving)return;const valid=flying.dataset.signature==='true';flying.remove();if(valid){state.signatureHits++;$('#signature-count').textContent=state.signatureHits;if(state.signatureHits>=5){finishMini(state.deck[state.index],true,'Пять подписей собраны');return}spawnSignatureCard(true)}else{spawnSignatureCard(false)}return}
  const doc=ev.target.closest('[data-doc]');if(doc){const buckets=state.deck[state.index].buckets;let idx=(Number(doc.dataset.bucket)+1)%buckets.length;doc.dataset.bucket=idx;doc.className=`sort-card assigned-${idx}`;doc.querySelector('strong').textContent=buckets[idx];return}
  if(ev.target.closest('#sort-submit')){const e=state.deck[state.index];const cards=$$('.sort-card');const good=cards.every((c,i)=>Number(c.dataset.bucket)===e.buckets.indexOf(e.documents[i][1]));finishMini(e,good,good?'Документы разложены правильно':'В стопках обнаружилась путаница');return}
  const sequenceSource=ev.target.closest('[data-sequence-source]');if(sequenceSource){if(Date.now()<state.sequenceSuppressClickUntil)return;if(sequenceSource.dataset.sequenceSource==='bank'){state.sequenceSelected=sequenceSource.dataset.seq;updateSequenceBoard();const nextSlot=document.querySelector('.sequence-slot:not(.filled)');if(nextSlot){const rect=nextSlot.getBoundingClientRect();if(rect.top<0||rect.bottom>window.innerHeight)nextSlot.scrollIntoView({block:'center',behavior:'smooth'})}}else clearSequenceSlot(Number(sequenceSource.dataset.slot));return}
  const sequenceSlot=ev.target.closest('.sequence-slot');if(sequenceSlot){if(Date.now()<state.sequenceSuppressClickUntil)return;const slotIndex=Number(sequenceSlot.dataset.slot);if(state.sequenceSelected)placeSequenceValue(state.sequenceSelected,slotIndex);else clearSequenceSlot(slotIndex);return}
  if(ev.target.closest('#sequence-submit')){const e=state.deck[state.index],good=state.sequencePlaced.every((value,i)=>value===e.sequence[i]);finishMini(e,good,'Проверка цепочки доступа');return}
  const find=ev.target.closest('[data-find]');if(find){const selected=$$('.find-item.selected');if(find.classList.contains('selected'))find.classList.remove('selected');else if(selected.length<2)find.classList.add('selected');$('#find-count').textContent=$$('.find-item.selected').length;return}
  if(ev.target.closest('#find-submit')){const e=state.deck[state.index],chosen=$$('.find-item.selected').map(b=>Number(b.dataset.find));finishMini(e,chosen.length===2&&e.targets.every(t=>chosen.includes(t)),'Сводка для команды');}
});
function $$(s){return [...document.querySelectorAll(s)]}
